var RoomTypes_DeleteRoomTypeSchemaJSON = `{"description":"Soft-deletes a RoomType; it is purged at expire_time unless restored.","properties":{"name":{"description":"Name of the RoomType to delete, \"hotels/{hotel}/roomTypes/{room_type}\".","pattern":"^hotels/[^/]+/roomTypes/[^/]+$","type":"string"}},"required":["name"],"type":"object"}`
var RoomTypes_GetRoomTypeSchemaJSON = `{"description":"Retrieves one RoomType.","properties":{"name":{"description":"Name of the RoomType to retrieve, \"hotels/{hotel}/roomTypes/{room_type}\".","pattern":"^hotels/[^/]+/roomTypes/[^/]+$","type":"string"}},"required":["name"],"type":"object"}`
var RoomTypes_ListRoomTypesSchemaJSON = `{"description":"Lists roomTypes, paginated per AIP-158 \u003chttps://aip.dev/158\u003e.","properties":{"filter":{"description":"Filter expression, AIP-160 \u003chttps://aip.dev/160\u003e.","type":"string"},"page_size":{"description":"Maximum roomTypes to return. Defaults to 50, capped at 1000.","maximum":1000,"minimum":0,"type":"integer"},"page_token":{"description":"Page token from a previous ListRoomTypesResponse.next_page_token.","type":"string"},"parent":{"description":"The Hotel whose roomTypes to list, \"hotels/{hotel}\".","type":"string"},"show_deleted":{"description":"Include soft-deleted roomTypes. AIP-164 \u003chttps://aip.dev/164\u003e.","type":"boolean"}},"required":["parent"],"type":"object"}`
